# ---------- 9. WhatsApp assistant (chat to order) ----------
CFGN='Config (verify hook)'
gv=webhook('WhatsApp Verify',[0,100],'vaigai-whatsapp','GET');gc=config([220,100],'Config (verify hook)')
gi=node('Verify token OK?','n8n-nodes-base.if',[440,100],{'conditions':{'options':{'caseSensitive':True,'leftValue':'','typeValidation':'loose'},'conditions':[{'id':uid(),'leftValue':"={{ $json.query['hub.verify_token'] }}",'rightValue':'={{ $json.wa_verify_token }}','operator':{'type':'string','operation':'equals'}},{'id':uid(),'leftValue':"={{ $json.query['hub.mode'] }}",'rightValue':'subscribe','operator':{'type':'string','operation':'equals'}}],'combinator':'and'},'options':{}},2)
gok=respond_text('Respond Challenge',[660,40],"={{ $json.query['hub.challenge'] }}");gno=respond_text('Respond Forbidden',[660,200],'forbidden',403)
CFGN='Config (messages)'
mw=node('WhatsApp Message Webhook','n8n-nodes-base.webhook',[0,600],{'httpMethod':'POST','path':'vaigai-whatsapp','responseMode':'responseNode','options':{'rawBody':True}},2,webhookId=uid());mc=config([220,600],'Config (messages)')
hm=crypto_hmac('HMAC body',[440,600],'',"={{ $('Config (messages)').first().json.wa_app_secret }}",True);sg=code('Check signature',[660,600],CODE['wa_sig']);si=ifnode('Signature valid?',[880,600],'={{ $json.ok }}','boolean','true')
r200=respond_text('Respond 200',[1100,540],'ok');r401=respond_text('Respond Bad Signature',[1100,700],'invalid signature',401)
pw=code('Parse WhatsApp event',[1320,540],CODE['wa_parse']);rs=sheet('Read WA Sessions',[1540,540],'WA Sessions','read');bb=code('Bot Brain',[1760,540],CODE['wa_brain'])
ss=sheet('Save session',[2000,380],'WA Sessions','appendOrUpdate',(WA_COLS,'$json.session'),)
ss['parameters']['columns']['matchingColumns']=['phone']
ex=code('Explode messages',[2000,540],CODE['wa_explode'])
send=node('Send WhatsApp message','n8n-nodes-base.httpRequest',[2480,540],{'method':'POST','url':"=https://graph.facebook.com/v20.0/{{ $('Config (messages)').first().json.wa_phone_id }}/messages",'sendHeaders':True,'headerParameters':{'parameters':[{'name':'Authorization','value':"=Bearer {{ $('Config (messages)').first().json.wa_token }}"},{'name':'Content-Type','value':'application/json'}]},'sendBody':True,'specifyBody':'json','jsonBody':'={{ JSON.stringify($json) }}','options':{}},4.2,onError='continueRegularOutput')
ho=ifnode('Has order?',[2000,700],'={{ $json.order ? true : false }}','boolean','true')
po=node('POST order','n8n-nodes-base.httpRequest',[2240,700],{'method':'POST','url':"={{ $('Config (messages)').first().json.base_url }}/webhook/vaigai-order",'sendHeaders':True,'headerParameters':{'parameters':[{'name':'x-vaigai-key','value':"={{ $('Config (messages)').first().json.api_key }}"},{'name':'Content-Type','value':'application/json'}]},'sendBody':True,'specifyBody':'json','jsonBody':"={{ JSON.stringify($('Bot Brain').first().json.order) }}",'options':{}},4.2,onError='continueRegularOutput')
oc=code('Order confirmation',[2480,700],CODE['wa_order_confirm'])
hl=ifnode('Has lead?',[2000,860],'={{ $json.lead ? true : false }}','boolean','true')
pl=node('POST lead','n8n-nodes-base.httpRequest',[2240,860],{'method':'POST','url':"={{ $('Config (messages)').first().json.base_url }}/webhook/vaigai-lead",'sendHeaders':True,'headerParameters':{'parameters':[{'name':'x-vaigai-key','value':"={{ $('Config (messages)').first().json.api_key }}"},{'name':'Content-Type','value':'application/json'}]},'sendBody':True,'specifyBody':'json','jsonBody':"={{ JSON.stringify($('Bot Brain').first().json.lead) }}",'options':{}},4.2,onError='continueRegularOutput')
ha=ifnode('Needs AI?',[2000,1020],'={{ $json.ai ? true : false }}','boolean','true')
pa=node('Ask AI assistant','n8n-nodes-base.httpRequest',[2240,1020],{'method':'POST','url':"={{ $('Config (messages)').first().json.base_url }}/webhook/vaigai-assistant",'sendHeaders':True,'headerParameters':{'parameters':[{'name':'x-vaigai-key','value':"={{ $('Config (messages)').first().json.api_key }}"},{'name':'Content-Type','value':'application/json'}]},'sendBody':True,'specifyBody':'json','jsonBody':"={{ JSON.stringify($('Bot Brain').first().json.ai) }}",'options':{}},4.2,onError='continueRegularOutput')
ar=code('AI reply to WhatsApp',[2480,1020],CODE['wa_ai_reply'])
n9=note("WHATSAPP ASSISTANT (chat to order)\nSame brain as the website. Customers message your WhatsApp Business number: ask prices, add products, check delivery, place a cash-on-delivery order, request a callback or report a problem. Their number is used automatically (no phone question). Unknown questions go to the AI agent (workflow 01) when ai_fallback is yes.\nSetup: Meta developer app, WhatsApp Cloud API, webhook URL = this workflow's /webhook/vaigai-whatsapp, verify token = wa_verify_token, subscribe to 'messages'. Messages are verified with your app secret (wa_app_secret). Create a 'WA Sessions' tab from sheets/WA Sessions.csv. Replies inside 24 hours need no template.\n"+STICKY_KEY,[0,-160],800,300)
nodes=[gv,gc,gi,gok,gno,mw,mc,hm,sg,si,r200,r401,pw,rs,bb,ss,ex,send,ho,po,oc,hl,pl,ha,pa,ar,n9]
cn=[LNK(gv['name'],gc['name']),LNK(gc['name'],gi['name']),LNK(gi['name'],gok['name'],0),LNK(gi['name'],gno['name'],1),
 LNK(mw['name'],mc['name']),LNK(mc['name'],hm['name']),LNK(hm['name'],sg['name']),LNK(sg['name'],si['name']),LNK(si['name'],r200['name'],0),LNK(si['name'],r401['name'],1),LNK(r200['name'],pw['name']),LNK(pw['name'],rs['name']),LNK(rs['name'],bb['name']),
 LNK(bb['name'],ss['name']),LNK(bb['name'],ex['name']),LNK(ex['name'],send['name']),LNK(bb['name'],ho['name']),LNK(ho['name'],po['name'],0),LNK(po['name'],oc['name']),LNK(oc['name'],send['name']),LNK(bb['name'],hl['name']),LNK(hl['name'],pl['name'],0),LNK(bb['name'],ha['name']),LNK(ha['name'],pa['name'],0),LNK(pa['name'],ar['name']),LNK(ar['name'],send['name'])]
save('09-vaigai-whatsapp-assistant.json',wf('Vaigai 09 · WhatsApp assistant (chat to order)',nodes,cn))
